CREATE TABLE IF NOT EXISTS projetos (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, descricao TEXT NOT NULL, imagem_url VARCHAR(500), link_url VARCHAR(500), status VARCHAR(40) NOT NULL, categoria VARCHAR(80) NOT NULL, tecnologias VARCHAR(1000) NOT NULL DEFAULT '', destaque BOOLEAN NOT NULL DEFAULT FALSE, ordem INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS servicos (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(160) NOT NULL, descricao TEXT NOT NULL, icone VARCHAR(80), ordem INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS habilidades (id BIGSERIAL PRIMARY KEY, categoria VARCHAR(120) NOT NULL, nome VARCHAR(120) NOT NULL, nivel INTEGER NOT NULL DEFAULT 1, ordem INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS qualificacoes (id BIGSERIAL PRIMARY KEY, titulo VARCHAR(200) NOT NULL, instituicao VARCHAR(200) NOT NULL, tipo VARCHAR(80), data_inicio VARCHAR(30), data_fim VARCHAR(30), descricao TEXT, imagem_url VARCHAR(500));
CREATE TABLE IF NOT EXISTS carreiras (id BIGSERIAL PRIMARY KEY, cargo VARCHAR(160) NOT NULL, empresa VARCHAR(160) NOT NULL, periodo VARCHAR(120) NOT NULL, tipo VARCHAR(80), descricao TEXT, conquistas TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS mensagens_contato (id BIGSERIAL PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, empresa VARCHAR(160), projeto VARCHAR(160), mensagem TEXT, data_envio TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, lida BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS usuarios_admin (id BIGSERIAL PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'ADMIN');
